CREATE TABLE businesses(id UUID PRIMARY KEY,name VARCHAR(150) NOT NULL,category VARCHAR(60),address VARCHAR(255),currency VARCHAR(3) NOT NULL DEFAULT 'NGN',vat_rate NUMERIC(5,2) NOT NULL DEFAULT 7.5,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users(id UUID PRIMARY KEY,business_id UUID NOT NULL REFERENCES businesses(id),email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,full_name VARCHAR(150) NOT NULL,role VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE products(id UUID PRIMARY KEY,business_id UUID NOT NULL REFERENCES businesses(id),name VARCHAR(200) NOT NULL,sku VARCHAR(60) NOT NULL,category VARCHAR(80),purchase_price NUMERIC(14,2) NOT NULL,selling_price NUMERIC(14,2) NOT NULL,quantity INT NOT NULL DEFAULT 0 CHECK(quantity>=0),min_stock INT NOT NULL DEFAULT 0,archived BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(business_id,sku));
CREATE TABLE inventory_movements(id UUID PRIMARY KEY,business_id UUID NOT NULL REFERENCES businesses(id),product_id UUID NOT NULL REFERENCES products(id),quantity_change INT NOT NULL,type VARCHAR(20) NOT NULL,reason VARCHAR(255),user_id UUID NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sales(id UUID PRIMARY KEY,business_id UUID NOT NULL REFERENCES businesses(id),user_id UUID NOT NULL REFERENCES users(id),subtotal NUMERIC(14,2) NOT NULL,tax NUMERIC(14,2) NOT NULL,total NUMERIC(14,2) NOT NULL,cogs NUMERIC(14,2) NOT NULL,payment_method VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sale_items(id UUID PRIMARY KEY,sale_id UUID NOT NULL REFERENCES sales(id),product_id UUID NOT NULL REFERENCES products(id),quantity INT NOT NULL CHECK(quantity>0),unit_price NUMERIC(14,2) NOT NULL,unit_cost NUMERIC(14,2) NOT NULL);
CREATE TABLE expenses(id UUID PRIMARY KEY,business_id UUID NOT NULL REFERENCES businesses(id),category VARCHAR(60) NOT NULL,description VARCHAR(255),amount NUMERIC(14,2) NOT NULL CHECK(amount>0),payment_method VARCHAR(20),expense_date DATE NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_sales_biz_date ON sales(business_id,created_at);
CREATE INDEX ix_mov_biz_prod ON inventory_movements(business_id,product_id,created_at);
CREATE INDEX ix_exp_biz_date ON expenses(business_id,expense_date);
